`timescale 1ns/1ps

// Self-checking testbench for npu_vector_unit, connected to a real npu_tcm.
//
// Two instances of the runner module tb_npu_vector_unit_run run in parallel:
// VLEN = 64 (the subsystem configuration, two 32-bit slices per register) on
// src/test/vectors/vector_unit_programs.txt and VLEN = 128 (four slices) on
// the smaller vector_unit_programs_v128.txt. Both files are generated by
// generate_vector_unit_vectors.py from the hx_vector reference model (whole
// unit: register file, TCM, illegal flag). Each program lists its TCM words
// (preloaded here through TCM port B), its commands and the expected final
// state. The VLEN = 64 program set covers:
//   - every arithmetic op x type over the corner cross products (saturation,
//     wrap, FP16 NaN / Inf / -0 / subnormals, max/min signed-zero rules,
//     relu(-0) and relu(NaN)), VSRA rounding over shifts 0, 1, lane-1, lane,
//     lane+1, 31 with garbage in scalar[31:5], VSPLAT truncation, VMOV,
//     the full TCM address width;
//   - hazards: RAW/WAW chains, WAR, VST then VLD of the same word, back-to-back
//     stores; illegal opcodes 11..31 and FP16 VSRA (dropped, sticky flag);
//   - performance programs (cycles per command for independent and
//     dependent streams of every op, reported as PERF lines);
//   - paced kernels (INT8 residual add, FP16 axpy; rolled loop, unrolled,
//     software-pipelined): commands arrive at the scalar core's rate, 3
//     cycles per instruction with `pre` scalar instructions in between, and
//     the end-to-end cycles to the final busy fall are reported as PERF;
//   - random programs (thousands of commands) with random cmd_valid gaps and
//     random tcm_gnt stalls (port A request gated between the unit and the
//     TCM).
// After the last command the testbench waits for busy to fall and, in that
// same cycle, compares the register file (hierarchical read of the unit's
// register-file array) and then reads the TCM words back through port B: busy
// low must mean every effect is visible. Monitors check every cycle that busy
// is exact (high exactly while an accepted command still has a register / TCM
// write ahead of it, or an accepted illegal command has not been dropped
// yet), that no register or TCM write happens while busy is low, and that a
// TCM request held without tcm_gnt keeps its address, direction and data,
// and that the X1 operand registers (datapath inputs) only change after an
// issue (clock enables: no datapath toggling while idle or stalled).
// The unit's tcm_rdata carries the TCM word only in the cycle after a granted
// read and random data in every other cycle, so a read captured late or from
// an ungranted request is caught. One program is also cut by a reset with
// commands in flight: busy, illegal and tcm_req must clear, cmd_ready must be
// high, and the program must then run correctly from the start. A directed
// check covers illegal_clear in the same cycle as a new illegal command (the
// new command wins). The VLEN = 128 set repeats the corner, SRA, splat /
// address, hazard, illegal and random (gaps, stalls, reset) programs.
module tb_npu_vector_unit;
    logic done64, done128;

    tb_npu_vector_unit_run #(
        .VLEN(64), .FILE_A("vectors/vector_unit_programs.txt"),
        .FILE_B("src/test/vectors/vector_unit_programs.txt")
    ) v64 (.done(done64));

    tb_npu_vector_unit_run #(
        .VLEN(128), .FILE_A("vectors/vector_unit_programs_v128.txt"),
        .FILE_B("src/test/vectors/vector_unit_programs_v128.txt")
    ) v128 (.done(done128));

    initial begin
        wait (done64 && done128);
        $display("PASS tb_npu_vector_unit vlen64: programs=%0d commands=%0d cycles=%0d backpressure_cycles=%0d gnt_stalls=%0d; vlen128: programs=%0d commands=%0d cycles=%0d",
                 v64.nprog, v64.total_cmds, v64.end_cycle, v64.stall_cycles, v64.gnt_stalls,
                 v128.nprog, v128.total_cmds, v128.end_cycle);
        $finish;
    end
endmodule

// One DUT + TCM + program runner for a given VLEN; done rises after the last
// program and the directed checks passed.
module tb_npu_vector_unit_run #(
    parameter integer VLEN = 64,
    parameter FILE_A = "vectors/vector_unit_programs.txt",
    parameter FILE_B = "src/test/vectors/vector_unit_programs.txt"
) (
    output logic done
);
    localparam integer NSLICE = VLEN / 32;
    localparam integer TCM_AW = 10;
    localparam integer MAXC = 4096;
    localparam integer MAXW = 1024;
    localparam integer MODE_GAPS = 1;
    localparam integer MODE_GNT = 2;
    localparam integer MODE_PERF = 4;
    localparam integer MODE_RESET = 8;
    localparam integer MODE_PACED = 16;

    logic clk = 1'b0;
    logic rst_n = 1'b0;
    always #5 clk = ~clk;

    // DUT command port
    logic              cmd_valid = 1'b0;
    logic              cmd_ready;
    logic [4:0]        cmd_op = '0;
    logic [1:0]        cmd_type = '0;
    logic [2:0]        cmd_vd = '0, cmd_vs1 = '0, cmd_vs2 = '0;
    logic [TCM_AW-1:0] cmd_addr = '0;
    logic [31:0]       cmd_scalar = '0;
    logic              busy, illegal;
    logic              illegal_clear = 1'b0;
    // TCM port A (through the grant gate)
    logic              tcm_req, tcm_we, tcm_gnt;
    logic [TCM_AW-1:0] tcm_addr;
    logic [VLEN-1:0]   tcm_wdata, tcm_rdata, mem_rdata;
    logic [VLEN-1:0]   rd_junk = '0;
    logic              rd_ok = 1'b0;
    logic [VLEN/8-1:0] tcm_wstrb;
    logic              gnt_allow = 1'b1;
    logic              a_req;
    // TCM port B (testbench)
    logic              b_req = 1'b0, b_we = 1'b0;
    logic [TCM_AW-1:0] b_addr = '0;
    logic [VLEN-1:0]   b_wdata = '0, b_rdata;
    logic              b_gnt;

    npu_vector_unit #(.VLEN(VLEN), .NREGS(8), .TCM_AW(TCM_AW)) dut (
        .clk(clk), .rst_n(rst_n),
        .cmd_valid(cmd_valid), .cmd_ready(cmd_ready), .cmd_op(cmd_op), .cmd_type(cmd_type),
        .cmd_vd(cmd_vd), .cmd_vs1(cmd_vs1), .cmd_vs2(cmd_vs2), .cmd_addr(cmd_addr),
        .cmd_scalar(cmd_scalar), .busy(busy), .illegal(illegal), .illegal_clear(illegal_clear),
        .tcm_req(tcm_req), .tcm_we(tcm_we), .tcm_addr(tcm_addr), .tcm_wdata(tcm_wdata),
        .tcm_wstrb(tcm_wstrb), .tcm_gnt(tcm_gnt), .tcm_rdata(tcm_rdata)
    );

    assign a_req = tcm_req && gnt_allow;

    // Port A read data is defined only in the cycle after a granted read
    // (architecture.md); npu_tcm also holds it afterwards, which would hide a
    // late capture, so the unit sees random data in every other cycle.
    always @(posedge clk) begin
        rd_ok <= a_req && !tcm_we;
        for (int j = 0; j < NSLICE; j++) rd_junk[j*32 +: 32] <= $urandom;
    end
    assign tcm_rdata = rd_ok ? mem_rdata : rd_junk;

    npu_tcm #(.WIDTH(VLEN), .DEPTH(1 << TCM_AW)) tcm (
        .clk(clk), .rst_n(rst_n),
        .a_req(a_req), .a_we(tcm_we), .a_addr(tcm_addr), .a_wdata(tcm_wdata),
        .a_wstrb(tcm_wstrb), .a_gnt(tcm_gnt), .a_rdata(mem_rdata),
        .b_req(b_req), .b_we(b_we), .b_addr(b_addr), .b_wdata(b_wdata),
        .b_wstrb({(VLEN/8){1'b1}}), .b_gnt(b_gnt), .b_rdata(b_rdata)
    );

    // ------------------------------------------------------------ program data
    reg [8*64-1:0]     name;
    integer            mode, nwords, ncmds, perf_start;
    logic [TCM_AW-1:0] w_addr [0:MAXW-1];
    logic [VLEN-1:0]   w_init [0:MAXW-1];
    logic [VLEN-1:0]   w_exp  [0:MAXW-1];
    logic [4:0]        c_op [0:MAXC-1];
    logic [1:0]        c_type [0:MAXC-1];
    logic [2:0]        c_vd [0:MAXC-1], c_vs1 [0:MAXC-1], c_vs2 [0:MAXC-1];
    logic [TCM_AW-1:0] c_addr [0:MAXC-1];
    logic [31:0]       c_scalar [0:MAXC-1];
    integer            c_pre [0:MAXC-1];
    logic [VLEN-1:0]   exp_rf [0:7];
    integer            exp_illegal;
    integer            t_accept [0:MAXC-1];

    integer file, status, nprog, p, i, k, total_cmds, cycle, stall_cycles, gnt_stalls;
    integer accepts, end_cycle;
    integer gnt_hold = 0;
    integer pend_eff = 0;     // register-slice and TCM writes still owed
    integer pend_ill = 0;     // accepted illegal commands not yet dropped
    reg [8*256-1:0] header;
    logic [VLEN-1:0] word;
    logic stall_mode;

    task automatic mismatch(input [8*96-1:0] what);
        begin
            $display("MISMATCH tb_npu_vector_unit: %0s (VLEN %0d, program %0s, cycle %0d)", what,
                     VLEN, name, cycle);
            $fatal(1);
        end
    endtask

    // ------------------------------------------------------------ monitors
    always @(posedge clk) begin
        cycle <= cycle + 1;
    end

    logic acc_d;
    logic hold_req, hold_we;
    logic [TCM_AW-1:0] hold_addr;
    logic [VLEN-1:0] hold_wdata;

    always @(posedge clk) begin
        acc_d <= rst_n && cmd_valid && cmd_ready;
        if (rst_n) begin
            if (cmd_valid && !cmd_ready) stall_cycles <= stall_cycles + 1;
            if (tcm_req && !tcm_gnt) gnt_stalls <= gnt_stalls + 1;
            if (!busy && tcm_req && tcm_we) mismatch("TCM write while busy is low");
            if (!busy && dut.rf_we) mismatch("register write while busy is low");
            if (hold_req) begin
                if (!tcm_req || tcm_we !== hold_we || tcm_addr !== hold_addr ||
                    (hold_we && tcm_wdata !== hold_wdata))
                    mismatch("TCM request changed before tcm_gnt");
            end
            if (tcm_req && tcm_we && tcm_wstrb !== {(VLEN/8){1'b1}})
                mismatch("tcm_wstrb not all ones on a store");
            hold_req <= tcm_req && !tcm_gnt;
            hold_we <= tcm_we;
            hold_addr <= tcm_addr;
            hold_wdata <= tcm_wdata;
        end else begin
            hold_req <= 1'b0;
        end
    end

    // Power: the X1 operand registers (the ALU, IMUL and FP16 inputs) load
    // only on issue, so they must hold while the unit is idle or stalled.
    logic [63:0] x1_prev;
    always @(posedge clk) begin
        if (rst_n && !dut.x1_v && {dut.x1_a, dut.x1_b} !== x1_prev)
            mismatch("X1 operands changed without an issue");
        x1_prev <= {dut.x1_a, dut.x1_b};
    end

    // Exact busy: compare with the outstanding effects of the accepted
    // commands (values of the cycle that ends at this edge), then account for
    // this cycle's writes, drops and handshake.
    always @(posedge clk) begin
        if (!rst_n) begin
            pend_eff = 0;
            pend_ill = 0;
        end else begin
            if (busy !== (pend_eff > 0 || pend_ill > 0)) begin
                $display("MISMATCH tb_npu_vector_unit: busy=%b with %0d writes and %0d illegal commands outstanding (VLEN %0d)",
                         busy, pend_eff, pend_ill, VLEN);
                mismatch("busy not exact");
            end
            if (dut.rf_we) pend_eff = pend_eff - 1;
            if (tcm_req && tcm_we && tcm_gnt) pend_eff = pend_eff - 1;
            if (dut.cur_valid && dut.cur_ill) pend_ill = pend_ill - 1;
            if (pend_eff < 0 || pend_ill < 0) mismatch("write or drop without a command");
            if (cmd_valid && cmd_ready) begin
                if (cmd_op > 5'd10 || (cmd_op == 5'd9 && cmd_type == 2'd3))
                    pend_ill = pend_ill + 1;
                else if (cmd_op == 5'd1)
                    pend_eff = pend_eff + 1;
                else
                    pend_eff = pend_eff + VLEN / 32;
            end
        end
    end

    always @(negedge clk) begin
        if (rst_n && acc_d && !busy) mismatch("busy low after an accepted command");
        // tcm_gnt stalls in bursts of 1..8 cycles
        if (stall_mode && gnt_hold > 0) begin
            gnt_allow <= 1'b0;
            gnt_hold <= gnt_hold - 1;
        end else if (stall_mode && ($urandom % 5) == 0) begin
            gnt_allow <= 1'b0;
            gnt_hold <= $urandom % 8;
        end else begin
            gnt_allow <= 1'b1;
            gnt_hold <= 0;
        end
    end

    // ------------------------------------------------------------ program file
    task automatic read_program;
        begin
            status = $fscanf(file, "%s %d %d %d %d\n", name, mode, nwords, ncmds, perf_start);
            if (status != 5 || nwords > MAXW || ncmds > MAXC) begin
                $display("MISMATCH tb_npu_vector_unit: bad program header (%0d)", p);
                $fatal(1);
            end
            for (k = 0; k < nwords; k = k + 1)
                status = $fscanf(file, "%h %h\n", w_addr[k], w_init[k]);
            for (k = 0; k < ncmds; k = k + 1)
                status = $fscanf(file, "%h %h %h %h %h %h %h %h\n", c_op[k], c_type[k], c_vd[k],
                                 c_vs1[k], c_vs2[k], c_addr[k], c_scalar[k], c_pre[k]);
            for (k = 0; k < 8; k = k + 1)
                status = $fscanf(file, "%h\n", exp_rf[k]);
            for (k = 0; k < nwords; k = k + 1)
                status = $fscanf(file, "%h %h\n", w_addr[k], w_exp[k]);
            status = $fscanf(file, "%d\n", exp_illegal);
            if (status != 1) begin
                $display("MISMATCH tb_npu_vector_unit: short program %0s", name);
                $fatal(1);
            end
        end
    endtask

    // ------------------------------------------------------------ run one program
    // reset_after >= 0: assert reset a few cycles after that command is
    // accepted, check the reset state and return without comparing.
    // Paced programs: the register-initialisation commands run first and
    // drain; from command perf_start on, command n is presented
    // 3 * (pre + 1) cycles after command n - 1 was accepted (scalar core
    // CPI 3) and the cycles until busy falls are reported.
    task automatic run_program(input integer reset_after);
        integer n, gap, waited, t0;
        reg done, paced;
        real per_cmd;
        begin
            // clear the sticky flag from the previous program
            @(negedge clk);
            illegal_clear = 1'b1;
            @(negedge clk);
            illegal_clear = 1'b0;
            if (illegal !== 1'b0) mismatch("illegal_clear did not clear illegal");
            // preload through port B, one word per cycle
            for (n = 0; n < nwords; n = n + 1) begin
                @(negedge clk);
                b_req = 1'b1; b_we = 1'b1; b_addr = w_addr[n]; b_wdata = w_init[n];
            end
            @(negedge clk);
            b_req = 1'b0; b_we = 1'b0;
            stall_mode = (mode & MODE_GNT) != 0;
            paced = (mode & MODE_PACED) != 0;
            done = 1'b0;
            t0 = 0;
            for (n = 0; n < ncmds && !done; n = n + 1) begin
                if (paced && n >= perf_start) begin
                    @(negedge clk);
                    cmd_valid = 1'b0;
                    cmd_op = 5'bx; cmd_vd = 3'bx; cmd_vs1 = 3'bx; cmd_vs2 = 3'bx;
                    if (n == perf_start) begin
                        while (busy) @(negedge clk);
                        t0 = cycle;
                    end else begin
                        while (cycle < t_accept[n-1] + 3 * (c_pre[n] + 1)) @(negedge clk);
                    end
                end else begin
                    if ((mode & MODE_GAPS) != 0 && ($urandom % 2) == 0) begin
                        gap = 1 + ($urandom % 4);
                        @(negedge clk);
                        cmd_valid = 1'b0;
                        cmd_op = 5'bx; cmd_vd = 3'bx; cmd_vs1 = 3'bx; cmd_vs2 = 3'bx;
                        repeat (gap - 1) @(negedge clk);
                    end
                    @(negedge clk);
                end
                cmd_valid = 1'b1;
                cmd_op = c_op[n]; cmd_type = c_type[n]; cmd_vd = c_vd[n];
                cmd_vs1 = c_vs1[n]; cmd_vs2 = c_vs2[n]; cmd_addr = c_addr[n];
                cmd_scalar = c_scalar[n];
                waited = 0;
                @(posedge clk);
                while (!cmd_ready) begin
                    waited = waited + 1;
                    if (waited > 1000) mismatch("cmd_ready stuck low");
                    @(posedge clk);
                end
                t_accept[n] = cycle;
                accepts = accepts + 1;
                if (n == reset_after) done = 1'b1;
            end
            @(negedge clk);
            cmd_valid = 1'b0;
            cmd_op = 5'bx; cmd_vd = 3'bx; cmd_vs1 = 3'bx; cmd_vs2 = 3'bx;
            if (reset_after >= 0) begin
                @(negedge clk);
                if (!busy) mismatch("reset test: nothing in flight");
                rst_n = 1'b0;
                #1;
                if (busy !== 1'b0 || illegal !== 1'b0 || tcm_req !== 1'b0 || cmd_ready !== 1'b1)
                    mismatch("outputs not cleared by reset");
                repeat (2) @(negedge clk);
                if (busy !== 1'b0 || tcm_req !== 1'b0) mismatch("outputs during reset");
                rst_n = 1'b1;
                repeat (2) @(negedge clk);
                if (busy !== 1'b0 || cmd_ready !== 1'b1 || illegal !== 1'b0)
                    mismatch("state after reset");
                stall_mode = 1'b0;
            end else begin
                waited = 0;
                while (busy) begin
                    @(negedge clk);
                    waited = waited + 1;
                    if (waited > 500) mismatch("busy stuck high");
                end
                if (paced) $display("PERF %0s cycles=%0d", name, cycle - t0);
                // busy just fell: every register and TCM write must be visible
                for (n = 0; n < 8; n = n + 1) begin
                    for (k = 0; k < NSLICE; k = k + 1)
                        word[k*32 +: 32] = dut.rf[n*NSLICE + k];
                    if (word !== exp_rf[n]) begin
                        $display("MISMATCH tb_npu_vector_unit: v%0d = %h expected %h", n, word,
                                 exp_rf[n]);
                        mismatch("register file");
                    end
                end
                stall_mode = 1'b0;
                // read back through port B, pipelined: one word per cycle
                for (n = 0; n <= nwords; n = n + 1) begin
                    @(negedge clk);
                    if (n > 0 && b_rdata !== w_exp[n-1]) begin
                        $display("MISMATCH tb_npu_vector_unit: TCM[%h] = %h expected %h",
                                 w_addr[n-1], b_rdata, w_exp[n-1]);
                        mismatch("TCM image");
                    end
                    b_req = (n < nwords); b_we = 1'b0;
                    if (n < nwords) b_addr = w_addr[n];
                end
                if (illegal !== exp_illegal[0]) mismatch("illegal flag");
                if ((mode & MODE_PERF) != 0 && !paced) begin
                    // steady state: accept interval over the second half
                    per_cmd = (t_accept[ncmds-1] - t_accept[(perf_start + ncmds) / 2]) * 1.0 /
                              (ncmds - 1 - (perf_start + ncmds) / 2);
                    $display("PERF %0s cycles_per_cmd=%0.2f", name, per_cmd);
                end
            end
        end
    endtask

    // illegal_clear in the same cycle as a new illegal command is dropped:
    // the new command wins and the flag stays set; a lone clear then clears.
    task automatic illegal_clear_race;
        begin
            @(negedge clk);
            illegal_clear = 1'b1;
            @(negedge clk);
            illegal_clear = 1'b0;
            if (illegal !== 1'b0 || busy !== 1'b0) mismatch("race test: not idle");
            cmd_valid = 1'b1;
            cmd_op = 5'd31; cmd_type = 2'd0; cmd_vd = 3'd1; cmd_vs1 = 3'd2; cmd_vs2 = 3'd3;
            @(posedge clk);
            if (cmd_ready !== 1'b1) mismatch("race test: command not accepted");
            @(negedge clk);
            cmd_valid = 1'b0;
            cmd_op = 5'bx;
            illegal_clear = 1'b1;
            if (!(dut.cur_valid && dut.cur_ill)) mismatch("race test: illegal command not executing");
            @(negedge clk);
            illegal_clear = 1'b0;
            if (illegal !== 1'b1) mismatch("illegal_clear won over a new illegal command");
            if (busy !== 1'b0) mismatch("busy after an illegal command was dropped");
            @(negedge clk);
            illegal_clear = 1'b1;
            @(negedge clk);
            illegal_clear = 1'b0;
            if (illegal !== 1'b0) mismatch("illegal_clear did not clear illegal");
        end
    endtask

    initial begin
        cycle = 0;
        stall_cycles = 0;
        gnt_stalls = 0;
        accepts = 0;
        total_cmds = 0;
        stall_mode = 1'b0;
        done = 1'b0;
        file = $fopen(FILE_A, "r");
        if (file == 0) file = $fopen(FILE_B, "r");
        if (file == 0) begin
            $display("MISMATCH tb_npu_vector_unit: cannot open %0s", FILE_B);
            $fatal(1);
        end
        status = $fgets(header, file);
        status = $fscanf(file, "%d\n", nprog);

        // reset state
        repeat (3) @(negedge clk);
        if (busy !== 1'b0 || illegal !== 1'b0 || tcm_req !== 1'b0)
            mismatch("outputs during the initial reset");
        rst_n = 1'b1;
        repeat (2) @(negedge clk);
        if (cmd_ready !== 1'b1 || busy !== 1'b0) mismatch("state after the initial reset");

        for (p = 0; p < nprog; p = p + 1) begin
            read_program();
            run_program(-1);
            total_cmds = total_cmds + ncmds;
            if ((mode & MODE_RESET) != 0) begin
                run_program(ncmds / 2);
                run_program(-1);
                total_cmds = total_cmds + ncmds;
            end
        end
        illegal_clear_race();
        if (stall_cycles == 0) mismatch("cmd_ready never applied backpressure");
        if (gnt_stalls == 0) mismatch("tcm_gnt never stalled a request");
        end_cycle = cycle;
        done = 1'b1;
    end
endmodule
